    93  exr_result_t
    94  DwaCompressor_construct (
    95      DwaCompressor*         me,
    96      AcCompression          acCompression,
    97      exr_encode_pipeline_t* encode,
    98      exr_decode_pipeline_t* decode)
    99  {
   100      exr_result_t rv = EXR_ERR_SUCCESS;
   101
   102      initializeFuncs ();
   103
   104      memset (me, 0, sizeof (DwaCompressor));
   105
   106      me->_acCompression = acCompression;
   107
   108      me->_encode = encode;
   109      me->_decode = decode;
   110
   111      if (encode)
   112      {
   113          const struct _internal_exr_context* pctxt = EXR_CCTXT (encode->context);
   114
   115          me->alloc_fn = pctxt ? pctxt->alloc_fn : internal_exr_alloc;
   116          me->free_fn  = pctxt ? pctxt->free_fn : internal_exr_free;
   117
   118          me->_channelData = internal_exr_alloc_aligned (
   119              me->alloc_fn,
   120              &(me->_channel_mem),
   121              sizeof (ChannelData) * (size_t) encode->channel_count,
   122              _SSE_ALIGNMENT);
   123          if (!me->_channelData) return EXR_ERR_OUT_OF_MEMORY;
   124
   125          memset (
   126              me->_channelData,
   127              0,
   128              sizeof (ChannelData) * (size_t) encode->channel_count);
   129
   130          me->_numChannels = encode->channel_count;
   131          for (int c = 0; c < encode->channel_count; ++c)
   132          {
   133              me->_channelData[c].chan        = encode->channels + c;
   134              me->_channelData[c].compression = UNKNOWN;
   135              DctCoderChannelData_construct (
   136                  &(me->_channelData[c]._dctData),
   137                  me->_channelData[c].chan->data_type);
   138          }
   139
   140          // DWAA should be 32, DWAB should be 256
   141          me->_numScanLines = encode->chunk.height;
   142
   143          me->_min[0] = encode->chunk.start_x;
   144          me->_min[1] = encode->chunk.start_y;
   145          me->_max[0] = me->_min[0] + encode->chunk.width - 1;
   146          me->_max[1] = me->_min[1] + encode->chunk.height - 1;
   147
   148          rv = exr_get_zip_compression_level (
   149              encode->context, encode->part_index, &(me->_zipLevel));
   150          if (rv != EXR_ERR_SUCCESS) return rv;
   151          rv = exr_get_dwa_compression_level (
   152              encode->context, encode->part_index, &(me->_dwaCompressionLevel));
   153          if (rv != EXR_ERR_SUCCESS) return rv;
   154      }
   155      else
   156      {
   157          const struct _internal_exr_context* pctxt = EXR_CCTXT (decode->context);
   158
   159          me->alloc_fn = pctxt ? pctxt->alloc_fn : internal_exr_alloc;
   160          me->free_fn  = pctxt ? pctxt->free_fn : internal_exr_free;
   161
   162          me->_channelData = internal_exr_alloc_aligned (
   163              me->alloc_fn,
   164              &(me->_channel_mem),
   165              sizeof (ChannelData) * (size_t) decode->channel_count,
   166              _SSE_ALIGNMENT);
   167          if (!me->_channelData) return EXR_ERR_OUT_OF_MEMORY;
   168
   169          memset (
   170              me->_channelData,
   171              0,
   172              sizeof (ChannelData) * (size_t) decode->channel_count);
   173
   174          me->_numChannels = decode->channel_count;
   175          for (int c = 0; c < decode->channel_count; ++c)
   176          {
   177              me->_channelData[c].chan        = decode->channels + c;
   178              me->_channelData[c].compression = UNKNOWN;
   179          }
   180
   181          me->_numScanLines = decode->chunk.height;
   182
   183          me->_min[0] = decode->chunk.start_x;
   184          me->_min[1] = decode->chunk.start_y;
   185          me->_max[0] = me->_min[0] + decode->chunk.width - 1;
   186          me->_max[1] = me->_min[1] + decode->chunk.height - 1;
   187      }
   188      return rv;
   189  }
