   193  static void
   194  DwaCompressor_destroy (DwaCompressor* me)
   195  {
   196      if (me->_packedAcBuffer) me->free_fn (me->_packedAcBuffer);
   197      if (me->_packedDcBuffer) me->free_fn (me->_packedDcBuffer);
   198      if (me->_rleBuffer) me->free_fn (me->_rleBuffer);
   199
   200      if (me->_channel_mem)
   201      {
   202          for (int c = 0; c < me->_numChannels; ++c)
   203              DctCoderChannelData_destroy (
   204                  me->free_fn, &(me->_channelData[c]._dctData));
   205
   206          me->free_fn (me->_channel_mem);
   207      }
   208
   209      if (me->_cscChannelSets) me->free_fn (me->_cscChannelSets);
   210      if (me->_channelRules != sLegacyChannelRules &&
   211          me->_channelRules != sDefaultChannelRules)
   212      {
   213          for (size_t i = 0; i < me->_channelRuleCount; ++i)
   214              Classifier_destroy (me->free_fn, &(me->_channelRules[i]));
   215          me->free_fn (me->_channelRules);
   216      }
