     1  exr_result_t
     2  DwaCompressor_uncompress (
     3      DwaCompressor* me,
     4      const uint8_t* inPtr,
     5      uint64_t       iSize,
     6      void*          uncompressed_data,
     7      uint64_t       uncompressed_size)
     8  {
     9      uint64_t     headerSize = NUM_SIZES_SINGLE * sizeof (uint64_t);
    10      exr_result_t rv         = EXR_ERR_SUCCESS;
    11      uint64_t     counters[NUM_SIZES_SINGLE];
    12      uint64_t     version;
    13      uint64_t     unknownUncompressedSize;
    14      uint64_t     unknownCompressedSize;
    15      uint64_t     acCompressedSize;
    16      uint64_t     dcCompressedSize;
    17      uint64_t     rleCompressedSize;
    18      uint64_t     rleUncompressedSize;
    19      uint64_t     rleRawSize;
    20
    21      uint64_t totalAcUncompressedCount;
    22      uint64_t totalDcUncompressedCount;
    23
    24      uint64_t acCompression;
    25
    26      size_t         outBufferSize;
    27      uint64_t       compressedSize;
    28      const uint8_t* dataPtr;
    29      uint64_t       dataLeft;
    30      uint8_t*       outBufferEnd;
    31      uint8_t*       packedAcBufferEnd;
    32      uint8_t*       packedDcBufferEnd;
    33      const uint8_t* compressedUnknownBuf;
    34      const uint8_t* compressedAcBuf;
    35      const uint8_t* compressedDcBuf;
    36      const uint8_t* compressedRleBuf;
    37
    38      if (iSize < headerSize) return EXR_ERR_CORRUPT_CHUNK;
    39
    40      //
    41      // Flip the counters from XDR to NATIVE
    42      //
    43
    44      memset (uncompressed_data, 0, uncompressed_size);
    45
    46      memcpy (counters, inPtr, headerSize);
    47      priv_to_native64 (counters, NUM_SIZES_SINGLE);
    48
    49      //
    50      // Unwind all the counter info
    51      //
    52      version                 = counters[VERSION];
    53      unknownUncompressedSize = counters[UNKNOWN_UNCOMPRESSED_SIZE];
    54      unknownCompressedSize   = counters[UNKNOWN_COMPRESSED_SIZE];
    55      acCompressedSize        = counters[AC_COMPRESSED_SIZE];
    56      dcCompressedSize        = counters[DC_COMPRESSED_SIZE];
    57      rleCompressedSize       = counters[RLE_COMPRESSED_SIZE];
    58      rleUncompressedSize     = counters[RLE_UNCOMPRESSED_SIZE];
    59      rleRawSize              = counters[RLE_RAW_SIZE];
    60
    61      totalAcUncompressedCount = counters[AC_UNCOMPRESSED_COUNT];
